#include <iostream>
#include <vector>
#include <cmath>
#include <algorithm>
#include <iomanip>
using namespace std;

int main(){
vector<double>level={1,1.2,1.35,1.45,1.55,1.6},x,y;for(int t=1;t<int(level.size());t++){x.push_back(level[t-1]);y.push_back(level[t]-level[t-1]);}double meanX=0,meanY=0,xx=0,xy=0;for(int i=0;i<int(x.size());i++){meanX+=x[i]/x.size();meanY+=y[i]/y.size();}for(int i=0;i<int(x.size());i++){xx+=pow(x[i]-meanX,2);xy+=(x[i]-meanX)*(y[i]-meanY);}cout<<"ADF slope "<<xy/xx<<"\n";
return 0;
}

